type Column<T> = { label: string; cell: (row: T, index: number) => React.ReactNode; className?: string };
type OrderRecord = (typeof seedOrders)[number];
function DataTable<T>({ rows, columns, onRow, empty = "No records to show" }: { rows: T[]; columns: Column<T>[]; onRow?: (row: T) => void; empty?: string }) {
  if (!rows.length) return <div className="admin-table-empty"><ClipboardList size={22} /><span>{empty}</span></div>;
  return <div className="admin-table-wrap"><table className="admin-table"><thead><tr>{columns.map(c => <th key={c.label} className={c.className}>{c.label}</th>)}</tr></thead><tbody>{rows.map((row, i) => <tr key={i} onClick={() => onRow?.(row)} className={onRow ? "clickable-row" : ""}>{columns.map(c => <td key={c.label} className={c.className}>{c.cell(row, i)}</td>)}</tr>)}</tbody></table></div>;
}

function Metric({ title, value, change, icon: Icon, hint }: { title: string; value: string; change?: string; icon: LucideIcon; hint?: string }) {
  return <div className="admin-metric"><div className="metric-top"><span>{title}</span><Icon size={17} /></div><b>{value}</b><div className="metric-foot">{change && <span className="metric-change"><ArrowUpRight size={13} />{change}</span>}{hint && <span>{hint}</span>}</div></div>;
}

