function PosSyncPage({ notify }: {notify:(s:string)=>void}) {
  const [syncing,setSyncing]=useState<string[]>([]);const [filter,setFilter]=useState("All stores");
  const retry=(code:string)=>{setSyncing(v=>[...v,code]);notify("POS synchronization started");window.setTimeout(()=>setSyncing(v=>v.filter(x=>x!==code)),1100)};
  const visible=filter==="Needs attention"?stores.filter(s=>s.pos!=="Connected"):stores;
  return <><PageTitle title="POS sync monitor" description="Keep store inventory and online availability working from the same source of truth." actions={<Button variant="secondary" onClick={()=>notify("All store syncs queued") }><RefreshCw size={14}/> Sync all stores</Button>}/><div className="system-banner"><span><Check size={17}/></span><div><b>All systems operational</b><small>22 of 24 stores synced in the last 10 minutes</small></div><StatusBadge status="Healthy"/></div><div className="admin-metrics-grid compact-metrics"><Metric title="Connected" value="22 / 24" icon={Activity}/><Metric title="Delayed" value="1" icon={RefreshCw}/><Metric title="Offline" value="1" icon={X}/><Metric title="Sync errors" value="14" icon={CircleHelp}/></div><section className="admin-panel full-panel"><div className="table-toolbar"><label><Search size={15}/><input placeholder="Search store or code"/></label><div><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All stores</option><option>Needs attention</option></select><button className="filter-button"><SlidersHorizontal size={14}/> City</button></div></div><DataTable rows={visible} columns={[{label:"Store",cell:s=><div><b>{s.name.replace("Brand Avenue - ","")}</b><small className="cell-sub">{s.city} · {s.code}</small></div>},{label:"POS version",cell:(_,i)=>`POS v${i===1?3:4}`},{label:"Last sync",cell:s=>s.sync},{label:"SKUs synced",cell:s=>s.products.toLocaleString("en-IN")},{label:"Latency",cell:(_,i)=>["1.2 sec","3.1 sec","2.4 sec","1.4 sec","1.8 sec"][i%5]},{label:"Errors",cell:(_,i)=><span className={i===1?"warning-text":""}>{i===1?14:0}</span>},{label:"Status",cell:s=><StatusBadge status={syncing.includes(s.code)?"Syncing":s.pos=== "Connected"?"Healthy":s.pos}/>},{label:"",cell:s=><Button variant="secondary" className="small-button" onClick={e=>{e.stopPropagation();retry(s.code)}} disabled={syncing.includes(s.code)}>{syncing.includes(s.code)?"Syncing…":"Retry sync"}</Button>} ]}/></section></>;
}

